"use client";

// Shared data store: demo data (generated by the real CIE engine) or the
// user's own exported files. Zustand keeps it simple — no backend needed.
//
// The workspace layout (inspired by a code-intelligence UI) has three zones:
//   topbar  — model picker + repo chip + main menus
//   stage   — the chart engine in the middle (map, charts, story pages)
//   chat    — Ask CIE on the right, wired to the stage
// so the store also carries which view the stage shows, any chart the chat
// asked it to render big, and the map bubble the user picked (which the chat
// offers as a referent).

import { create } from "zustand";
import type { CieReport, CieViewSpec, ConceptTree, VizElement, CieDeps, CieRuntime, CieStories, CieQuality, CieCochange, CieOverlap, CieDrift } from "./cie-types";
import type { TechStack } from "./stack-types";
import type { ChatChartSpec, MasteryCardData } from "./chat-chart";
import type { RepoScan } from "./language-profiles";
import { DEFAULT_LLM, loadLlmConfig, saveLlmConfig, type LlmConfig } from "./llm-config";
import { freshMastery, loadMasteryState, masteryKeyOf, saveMasteryState, type MasteryState } from "./mastery";
import { ATLAS_RESET, scopeForRef, type AtlasRef, type AtlasSelection } from "./atlas";

export type DataSource = "demo" | "custom" | null;

// Every page the middle stage can show. "chart" renders a chart the chat
// (or a menu tap) sent to the canvas. "mastery" is the guided 5-station
// journey. "atlas" is the multi-view dashboard — four synchronized views
// over one Selection Context (lib/atlas.ts).
export type StageView =
  | "start"
  | "map"
  | "does"
  | "fixes"
  | "promises"
  | "numbers"
  | "menu"
  | "trust"
  | "deps"
  | "runtime"
  | "quality"
  | "mastery"
  | "atlas"
  | "chart";

// One bubble in the "Ask CIE" conversation. `chart` is the complementary
// chart the AI attached to its answer (US-020 catalog pick), if any. Failed
// sends carry `technical` (collapsible) and `providerIssue` (offer to open
// the connection settings). `instant` marks answers drawn locally from the
// loaded store (draw-anything.ts) — no AI was involved, and the footer says
// so instead of naming a provider.
//        (or a menu tap) sent to the canvas.
export interface ChatMessage {
  role: "user" | "assistant";
  content: string;
  error?: boolean;
  chart?: ChatChartSpec;
  card?: MasteryCardData; // mastery journey cards — entry points, flows, trace (with the verify loop), 5 things
  technical?: string;
  providerIssue?: boolean;
  instant?: boolean;
}

/**
 * "Show me the code" — a chart element with a known source location opened
 * the source panel. Carries everything the panel needs: where to look, which
 * byte offsets/line to highlight, and which chart element asked (so the
 * panel's "Ask CIE about this" button can hand a grounded question to chat).
 */
export interface SourceViewerRequest {
  file: string; // repo-relative path, exactly as the exports name it
  line?: number; // flat real line number when the export carried one
  endLine?: number;
  byteStart?: number; // report.json symbols[].loc — resolved to a line
  byteEnd?: number; // only when the file's content is available
  elName?: string;
  elValue?: number | string;
  chartTitle?: string;
}

interface CieState {
  report: CieReport | null;
  viewspec: CieViewSpec | null;
  concepts: ConceptTree | null;
  deps: CieDeps | null; // dependency manifests (cie deps export) — null when none
  runtime: CieRuntime | null; // collected runtime evidence — null when the project has none
  stories: CieStories | null; // the 33 story demos with real data — null when the project has none
  quality: CieQuality | null; // health/quality ETL export — null when the project has none
  cochange: CieCochange | null; // git co-change coupling (cie cochange) — null when none, or too shallow a clone to mine
  overlap: CieOverlap | null; // capability overlap over the concept tree (cie overlap) — null when none
  drift: CieDrift | null; // real claim-extraction + verification over the project's own docs (cie drift) — null when no docs found
  stack: TechStack | null; // the engine's tech-stack artifact (cie stack) — null when the pass found nothing
  source: DataSource;
  label: string;
  loading: boolean;
  loadError: string;
  chat: ChatMessage[];
  chatBusy: boolean;
  jobId: string | null; // active "Connect a repo" job, survives dialog close
  repoScan: RepoScan | null; // language inventory from connect-a-repo flows

  // mastery journey — per-project state, localStorage-backed (lib/mastery.ts).
  // Null until the owning components load it after mount (browser-only API).
  mastery: MasteryState | null;
  pendingTrace: { entryId: number; title: string } | null; // a card handed a trace to the chat

  // workspace state
  view: StageView; // what the middle stage shows
  canvasChart: ChatChartSpec | null; // the chart sent to the canvas (view === "chart")
  mapSelected: VizElement | null; // map bubble picked; the chat offers it as a referent
  llm: LlmConfig; // who answers — hydrated from localStorage after mount
  llmSettingsOpen: boolean; // the connection settings dialog (topbar owns it)
  pendingAsk: string | null; // click-to-chat: a question any chart/card handed to the chat

  // atlas dashboard — the Selection Context (lib/atlas.ts). One click
  // updates this; all four views re-render from it.
  atlasSelection: AtlasSelection;
  atlasView: "containers" | "components" | "sequence" | "dataflow";
  atlasFactsOnly: boolean; // "Facts only" — dim/filter inferred elements everywhere

  // source panel — click a chart element with a location, see the code
  sourceViewer: SourceViewerRequest | null;
  sourceRoot: string | null; // absolute root of a consented local-folder project (URL clones are deleted after analysis — null there, honestly)
  sourceCache: Record<string, string>; // fetched file contents, by repo-relative path

  demoKind: "banking" | "spring" | "polyglot"; // which bundled sample is loaded
  loadDemo: (kind?: "banking" | "spring" | "polyglot") => Promise<void>;
  loadSpringDemo: () => Promise<void>; // the second bundled sample — the Spring/Java+Kotlin stand-in
  loadPolyglotDemo: () => Promise<void>; // the polyglot five-service sample — the default one
  setCustom: (
    report: CieReport | null,
    viewspec: CieViewSpec | null,
    concepts: ConceptTree | null,
    label: string,
    extra?: {
      repoScan?: RepoScan | null;
      deps?: CieDeps | null;
      runtime?: CieRuntime | null;
      stories?: CieStories | null;
      quality?: CieQuality | null;
      cochange?: CieCochange | null;
      overlap?: CieOverlap | null;
      drift?: CieDrift | null;
      stack?: TechStack | null;
      sourceRoot?: string | null;
    }
  ) => void;
  reset: () => void;
  pushChat: (m: ChatMessage) => void;
  setChatBusy: (b: boolean) => void;
  clearChat: () => void;
  setJobId: (id: string | null) => void;
  setView: (v: StageView) => void;
  openChartOnCanvas: (spec: ChatChartSpec) => void;
  closeCanvasChart: () => void;
  setMapSelected: (el: VizElement | null) => void;
  setPendingAsk: (q: string | null) => void;
  setLlm: (cfg: LlmConfig) => void;
  hydrateLlm: () => void;
  setLlmSettingsOpen: (open: boolean) => void;
  openSourceViewer: (req: SourceViewerRequest) => void;
  closeSourceViewer: () => void;
  cacheSource: (path: string, content: string) => void;

  // atlas dashboard
  setAtlasSelection: (ref: AtlasRef | null) => void; // click anywhere in any view
  drillUp: () => void; // breadcrumb: reset to the level above
  resetAtlas: () => void; // empty space / System crumb
  setAtlasView: (v: "containers" | "components" | "sequence" | "dataflow") => void;
  setAtlasFactsOnly: (b: boolean) => void;

  // mastery journey
  loadMastery: () => void; // (re)load for the CURRENT project; call after mount / project change
  updateMastery: (fn: (m: MasteryState) => MasteryState) => void; // pure edit + persist
  resetMastery: () => void; // start over — but never silently: callers confirm first
  setPendingTrace: (t: { entryId: number; title: string } | null) => void;
}

export const useCie = create<CieState>((set, get) => ({
  report: null,
  viewspec: null,
  concepts: null,
  deps: null,
  runtime: null,
  stories: null,
  quality: null,
  cochange: null,
  overlap: null,
  drift: null,
  stack: null,
  demoKind: "polyglot",
  source: null,
  label: "",
  loading: true,
  loadError: "",
  chat: [],
  chatBusy: false,
  jobId: null,
  repoScan: null,
  mastery: null,
  pendingTrace: null,
  view: "start",
  canvasChart: null,
  mapSelected: null,
  llm: DEFAULT_LLM,
  llmSettingsOpen: false,
  pendingAsk: null,
  sourceViewer: null,
  sourceRoot: null,
  sourceCache: {},
  atlasSelection: ATLAS_RESET,
  atlasView: "containers",
  atlasFactsOnly: false,

  loadDemo: async (kind) => {
    const demoKind = kind ?? get().demoKind ?? "polyglot";
    const dir = demoKind === "spring" ? "/data/spring" : demoKind === "polyglot" ? "/data/polyglot" : "/data";
    set({ loading: true, loadError: "" });
    try {
      // deps.json + runtime.json + stories.json are optional extras: a project
      // without them still loads, and those views show honest empty states.
      // cochange.json is deliberately not bundled: the sample lives inside
      // this engine's own monorepo without its own .git root, so `cie
      // cochange` there would mine the ENGINE's commit history, not the
      // sample's — honestly null beats a misleading real-looking chart.
      const [report, viewspec, concepts, deps, runtime, stories, quality, overlap, drift, stack] = await Promise.all([
        fetch(`${dir}/report.json`).then((r) => r.json()),
        fetch(`${dir}/viewspec.json`).then((r) => r.json()),
        fetch(`${dir}/concepts.json`).then((r) => r.json()),
        fetch(`${dir}/deps.json`).then((r) => r.json()).catch(() => null),
        fetch(`${dir}/runtime.json`).then((r) => r.json()).catch(() => null),
        fetch(`${dir}/stories.json`).then((r) => r.json()).catch(() => null),
        fetch(`${dir}/quality.json`).then((r) => r.json()).catch(() => null),
        fetch(`${dir}/overlap.json`).then((r) => r.json()).catch(() => null),
        fetch(`${dir}/drift.json`).then((r) => r.json()).catch(() => null),
        fetch(`${dir}/stack.json`).then((r) => r.json()).catch(() => null),
      ]);
      set({
        report,
        viewspec,
        concepts,
        deps,
        runtime,
        stories,
        quality,
        cochange: null,
        overlap,
        drift,
        stack,
        demoKind,
        source: "demo",
        label:
          demoKind === "spring"
            ? "Sample project: a Spring Boot service (13 files — Java + Kotlin, Docker, PostgreSQL)"
            : demoKind === "polyglot"
              ? "Sample project: a five-service harbor system (37 files — Java, Kotlin, Rust, TypeScript and Python, one compose file)"
              : "Sample project: a small banking app (13 files — Python, SQL and shell)",
        loading: false,
        chat: [],
        chatBusy: false,
        repoScan: null,
        view: "start",
        canvasChart: null,
        mapSelected: null,
        // The sample project has no local-folder root on this machine.
        // Switching away from a connected project must drop its source
        // state too, or the panel would try to resolve demo files against
        // the stale root — surfacing wrong-project code or a confusing
        // read error (issue #6). Mirrors setCustom()'s reset.
        sourceRoot: null,
        sourceCache: {},
        sourceViewer: null,
        pendingAsk: null,
        atlasSelection: ATLAS_RESET,
        atlasView: "containers",
        atlasFactsOnly: false,
      });
    } catch {
      set({ loading: false, loadError: "Could not load the sample data. Please refresh the page." });
    }
  },

  setCustom: (report, viewspec, concepts, label, extra) =>
    set({
      report,
      viewspec,
      concepts,
      deps: extra?.deps ?? null,
      runtime: extra?.runtime ?? null,
      stories: extra?.stories ?? null,
      quality: extra?.quality ?? null,
      cochange: extra?.cochange ?? null,
      overlap: extra?.overlap ?? null,
      drift: extra?.drift ?? null,
      stack: extra?.stack ?? null,
      source: "custom",
      label,
      loading: false,
      loadError: "",
      chat: [],
      chatBusy: false,
      // The scan only exists for connect-a-repo flows; switching to the
      // sample or to uploaded files honestly drops it.
      repoScan: extra?.repoScan ?? null,
      // Only local-folder projects keep a readable root on this machine.
      // URL clones are deleted after analysis and uploads never touched
      // disk — the source panel says so honestly for those.
      sourceRoot: extra?.sourceRoot ?? null,
      sourceCache: {},
      sourceViewer: null,
      // A new project starts on its own front page, not on an old chart.
      view: get().view === "chart" ? "start" : get().view,
      canvasChart: null,
      mapSelected: null,
      atlasSelection: ATLAS_RESET,
      atlasView: "containers",
      atlasFactsOnly: false,
    }),

  reset: () => {
    void useCie.getState().loadDemo(useCie.getState().demoKind);
  },

  loadSpringDemo: async () => {
    await useCie.getState().loadDemo("spring");
  },

  loadPolyglotDemo: async () => {
    await useCie.getState().loadDemo("polyglot");
  },

  pushChat: (m) => set((s) => ({ chat: [...s.chat, m] })),
  setChatBusy: (b) => set({ chatBusy: b }),
  clearChat: () => set({ chat: [] }),
  setJobId: (id) => set({ jobId: id }),

  setView: (v) => set({ view: v }),

  openChartOnCanvas: (spec) => set({ canvasChart: spec, view: "chart" }),
  closeCanvasChart: () => set({ canvasChart: null, view: "start" }),

  setMapSelected: (el) => set({ mapSelected: el }),

  setPendingAsk: (q) => set({ pendingAsk: q }),

  setLlm: (cfg) => {
    saveLlmConfig(cfg);
    set({ llm: cfg });
  },

  // Called once after mount (localStorage is browser-only).
  hydrateLlm: () => set({ llm: loadLlmConfig() }),

  setLlmSettingsOpen: (open) => set({ llmSettingsOpen: open }),

  openSourceViewer: (req) => set({ sourceViewer: req }),
  closeSourceViewer: () => set({ sourceViewer: null }),
  cacheSource: (path, content) => set((s) => ({ sourceCache: { ...s.sourceCache, [path]: content } })),

  // atlas — a click anywhere lands here; the scope follows the ref kind.
  // Clicking the already-selected thing again zooms back out one level
  // (toggle), so drill-down never becomes a trap.
  setAtlasSelection: (ref) =>
    set((s) => {
      if (!ref) return { atlasSelection: ATLAS_RESET };
      if (s.atlasSelection.primary?.kind === ref.kind && s.atlasSelection.primary?.id === ref.id) {
        return { atlasSelection: ATLAS_RESET }; // second click = release
      }
      return { atlasSelection: { primary: ref, scope: scopeForRef(ref) } };
    }),
  drillUp: () =>
    set((s) => {
      const p = s.atlasSelection.primary;
      if (!p) return {};
      if (p.kind === "symbol") {
        const file = p.loc?.file;
        return file
          ? { atlasSelection: { primary: { kind: "module", id: file, label: file.split("/").pop() ?? file, loc: { file } }, scope: "module" } }
          : { atlasSelection: ATLAS_RESET };
      }
      if (p.kind === "module" || p.kind === "store") {
        const i = p.id.indexOf("/");
        return i > 0
          ? { atlasSelection: { primary: { kind: "container", id: p.id.slice(0, i), label: p.id.slice(0, i) }, scope: "container" } }
          : { atlasSelection: ATLAS_RESET };
      }
      return { atlasSelection: ATLAS_RESET };
    }),
  resetAtlas: () => set({ atlasSelection: ATLAS_RESET }),
  setAtlasView: (v) => set({ atlasView: v }),
  setAtlasFactsOnly: (b) => set({ atlasFactsOnly: b }),

  // mastery: keyed by the loaded project (label); load reads localStorage.
  // Switching projects drops the old state from memory so every component
  // that renders it re-reads the right person's journey.
  loadMastery: () => {
    const key = masteryKeyOf(get().source, get().label);
    set((s) => (s.mastery?.key === key ? s : { mastery: loadMasteryState(key) }));
  },
  updateMastery: (fn) => {
    const m = get().mastery;
    if (!m) return; // loaded after mount only
    const next = fn(m);
    if (next === m) return;
    set({ mastery: next });
    saveMasteryState(next);
  },
  resetMastery: () => {
    const key = masteryKeyOf(get().source, get().label);
    const fresh = freshMastery(key);
    set({ mastery: fresh });
    saveMasteryState(fresh);
  },
  setPendingTrace: (t) => set({ pendingTrace: t }),
}));
